SG.F = {
  A: 0.6, B: 0.008,        // 攻擊 = 兵種基礎攻擊 ×（A + 屬性 × B）；普攻用武力，法術用智力
  DR: 0.002,               // 減傷 = 武力 × DR
  P0: 0.5, PK: 0.01, LO: 0.1, HI: 0.95,   // 法術成功率 = P0 +（我方智力 − 目標智力）× PK
  REC: 0.001,              // 招降：每擊敗 1 名敵將的機率 = 隊伍平均魅力 × REC
  UR_ATK: 1.15,            // ★暫定：UR 攻擊加成（舊 1.6 ÷ 1.4），等 UR 數值表定案再改
};
SG.atkOf = function (typ, stat, x) { return Math.round(SG.TYPES[typ].atk * (SG.F.A + stat * SG.F.B) * (x || 1) / 5) * 5; };
SG.spellChance = function (za, zd) { return Math.min(SG.F.HI, Math.max(SG.F.LO, SG.F.P0 + (za - zd) * SG.F.PK)); };

