SG.unitStats = function (card, rar, star) {
  var t = SG.TYPES[card.typ], up = SG.RAR.indexOf(rar) >= 2;
  var w = card.w, z = card.z, m = card.m;
  if (up) { if (card.bk === "武") w = Math.min(100, w + card.bv); else if (card.bk === "智") z = Math.min(100, z + card.bv); else m = Math.min(100, m + card.bv); }
  var x = card.ur ? SG.F.UR_ATK : 1;
  var am = SG.atkOf(card.typ, w, x), asp = SG.atkOf(card.typ, z, x);
  return { hp: Math.round(SG.hpOf(rar, star) * t.hp), w: w, z: z, m: m, am: am, asp: asp, atk: card.typ === "法" ? asp : am, dr: w * SG.F.DR, up: up };
};
